<?php
declare(strict_types=1);
require dirname(__DIR__, 2).'/app/bootstrap.php';
try {
 $year=clean_year($_GET['year'] ?? launch_fiscal_year());
 $plans=sql("SELECT p.*,COUNT(i.id) AS activity_count,COALESCE(SUM(i.budget),0) AS allocation FROM youth_plans p LEFT JOIN youth_plan_items i ON i.plan_id=p.id WHERE p.status='published' AND p.fiscal_year<=? AND p.end_year>=? GROUP BY p.id ORDER BY p.plan_type,p.id DESC",[$year,$year])->fetchAll();
 $id=(int)($_GET['id'] ?? 0);
 $selected=$id ? sql("SELECT * FROM youth_plans WHERE id=? AND status='published'",[$id])->fetch() : null;
 $items=$selected ? sql('SELECT * FROM youth_plan_items WHERE plan_id=? ORDER BY id',[$id])->fetchAll() : [];
} catch (Throwable $ex) { render_failure($ex); }
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="description" content="Published CBYDP and ABYIP plans of SK Barangay Bantog, Tarlac City."><title>Youth Development Plans | SK Bantog</title><link rel="stylesheet" href="assets/css/site.css"><link rel="stylesheet" href="assets/css/plans.css"></head><body>
<header class="site-header"><div class="shell header-inner"><a class="brand" href="index.php"><img class="brand-logo" src="assets/images/sk-bantog-logo.webp" width="50" height="50" alt=""><span class="brand-label"><strong>SK BARANGAY BANTOG</strong><small>YOUTH DEVELOPMENT & INVESTMENT PLANS</small></span></a><a class="btn btn-outline" href="index.php">← Public portal</a></div></header>
<main><section class="page-banner"><div class="shell"><span class="overline">OFFICIAL PUBLIC DISCLOSURE · FY <?= $year ?></span><h1>Youth development plans</h1><p>Explore published programs, priorities, targets, and planned allocations of the Sangguniang Kabataan of Barangay Bantog.</p></div></section>
<div class="shell inner-content"><form method="get" class="filter-form"><label for="year">Fiscal year</label><input id="year" type="number" name="year" min="2020" max="2100" value="<?= $year ?>"><button class="btn btn-primary">View plans</button></form>
<?php if($id && !$selected): ?><p class="alert error">This plan is not available for public viewing.</p><?php endif; ?>
<?php if($selected): ?><div class="plans-subnav"><a href="plans.php?year=<?= $year ?>">← All published plans</a><span><?= e($selected['plan_type']) ?> · <?= (int)$selected['fiscal_year'] ?>–<?= (int)$selected['end_year'] ?></span></div><section class="admin-panel plans-activities"><span class="overline">APPROVED PUBLICATION</span><h2><?= e($selected['title']) ?></h2><p><?= e($selected['description']) ?></p><div class="table-scroll"><table><thead><tr><th>Focus area / program</th><th>Concern / objective</th><th>Target / implementation</th><th>Proposed budget</th></tr></thead><tbody><?php foreach($items as $item): ?><tr><td><strong><?= e($item['program_title']) ?></strong><small><?= e($item['center_of_participation']) ?></small></td><td><?= e($item['youth_concern']) ?><small><?= e($item['objective']) ?></small></td><td><?= e($item['target_beneficiaries']) ?><small><?= e($item['implementation_period']) ?> · <?= e($item['responsible_person']) ?></small></td><td><?= $item['budget']===null?'—':e(cash($item['budget'])) ?></td></tr><?php endforeach; ?></tbody></table></div><p class="muted">This online presentation summarizes the published plan. Refer to the approved signed document for official submissions and verification.</p></section>
<?php else: ?><div class="plans-heading"><span class="overline">PLANNING & ACCOUNTABILITY</span><h1>Published plans for <?= $year ?></h1><p>CBYDP is the multi-year youth development framework; ABYIP contains annual planned programs and activities.</p></div><div class="plans-columns"><?php if(!$plans): ?><div class="admin-panel"><h2>Awaiting official publication</h2><p>No approved CBYDP or ABYIP has been published for this fiscal year. Please check again after official approval.</p></div><?php endif; ?><?php foreach($plans as $p): ?><a class="admin-panel plan-list-item" href="plans.php?id=<?= (int)$p['id'] ?>&year=<?= $year ?>"><span><span class="overline"><?= e($p['plan_type']) ?> · FY <?= (int)$p['fiscal_year'] ?><?= $p['end_year']!=$p['fiscal_year']?'–'.(int)$p['end_year']:'' ?></span><b><?= e($p['title']) ?></b><small><?= (int)$p['activity_count'] ?> planned activities · <?= e(cash($p['allocation'])) ?> entered allocations</small></span><em>View plan →</em></a><?php endforeach; ?></div><?php endif; ?></div></main></body></html>